"""Compare raw EVA occurrence-gap correlations with layout-aware public controls."""

from collections import Counter
from dataclasses import replace
import json
from pathlib import Path
from random import Random
import sys

import numpy as np

from vs import corpus, generators
from voynich_gap_surrogates import (
    shuffle_global_tokens,
    shuffle_whole_lines_within_page,
    shuffle_whole_words_within_paragraph,
    stationary_word_copy,
)


def eligible(line, alphabet):
    return line.unit == 'P' and line.words and all(set(word) <= alphabet for word in line.words)


def source_layout(pages, common):
    selected = []
    template = []
    for page in pages:
        paragraphs = []
        group = []
        filtered = []
        for line in page.lines:
            if line.unit != 'P':
                continue
            if line.para_start and group:
                paragraphs.append(group)
                group = []
            if line.id in common:
                filtered.append(line)
                group.append(line.id)
            if line.para_end and group:
                paragraphs.append(group)
                group = []
        if group:
            paragraphs.append(group)
        if filtered:
            selected.append(replace(page, lines=filtered))
            template.append(paragraphs)
    return selected, template


def to_book(pages, layout):
    return [
        [[by_id[line_id] for line_id in group] for group in groups]
        for page, groups in zip(pages, layout, strict=True)
        for by_id in [{line.id: line.words for line in page.lines}]
    ]


def shuffle_line_glyph_slots(book, rng):
    def shuffled(line):
        glyphs = list(''.join(line))
        rng.shuffle(glyphs)
        result = []
        offset = 0
        for word in line:
            result.append(''.join(glyphs[offset:offset + len(word)]))
            offset += len(word)
        return result

    return [[[shuffled(line) for line in group] for group in page] for page in book]


def book_streams(book):
    return [
        np.frombuffer(' '.join(word for group in page for line in group for word in line).encode('ascii'), dtype=np.uint8)
        for page in book
    ]


def pearson_gap_curve(gap_sequences, max_lag, min_pairs):
    count = np.zeros(max_lag)
    sx = np.zeros(max_lag)
    sy = np.zeros(max_lag)
    sxx = np.zeros(max_lag)
    syy = np.zeros(max_lag)
    sxy = np.zeros(max_lag)
    for gaps in gap_sequences:
        values = np.asarray(gaps, dtype=float)
        length = len(values)
        size = min(max_lag, length - 1)
        if size <= 0:
            continue
        lags = np.arange(1, size + 1)
        terms = length - lags
        csum = np.concatenate(([0.0], np.cumsum(values)))
        sqsum = np.concatenate(([0.0], np.cumsum(values ** 2)))
        count[:size] += terms
        sx[:size] += csum[terms]
        sy[:size] += csum[-1] - csum[lags]
        sxx[:size] += sqsum[terms]
        syy[:size] += sqsum[-1] - sqsum[lags]
        if length > 256:
            sxy[:size] += np.array([np.dot(values[:-lag], values[lag:]) for lag in lags])
        else:
            sxy[:size] += np.correlate(values, values, mode='full')[length - 1 + lags]
    with np.errstate(divide='ignore', invalid='ignore'):
        variance = (sxx - sx * sx / count) * (syy - sy * sy / count)
        curve = (sxy - sx * sy / count) / np.sqrt(variance)
    return np.where((count >= min_pairs) & (variance > 0), curve, np.nan)


def curves(book, symbols, plan):
    streams = book_streams(book)
    if plan.get('flatten_pages', False):
        separator = np.array([ord(' ')], dtype=np.uint8)
        streams = [np.concatenate([item for stream in streams for item in (stream, separator)])[:-1]]
    return np.array([
        pearson_gap_curve(
            [np.diff(np.flatnonzero(stream == ord(symbol))) for stream in streams],
            plan['max_lag'], plan['min_pairs_per_coefficient'],
        )
        for symbol in symbols
    ])


def numeric(array):
    return np.where(np.isfinite(array), array, None).tolist()


def mean_summary(observed, replicas, mask):
    selected = observed[mask]
    if not selected.size:
        return None
    value = float(selected.mean())
    nulls = replicas[:, mask].mean(axis=1)
    return {
        'observed': value,
        'null_mean': float(nulls.mean()),
        'null_95': [float(q) for q in np.quantile(nulls, (.025, .975))],
        'upper_tail_p': (1 + int((nulls >= value - 1e-12).sum())) / (1 + len(nulls)),
        'common_coefficients': int(selected.size),
    }


def compare(observed, nulls, symbols, plan):
    common = np.isfinite(observed) & np.logical_and.reduce([
        np.isfinite(replicas).all(axis=0) for replicas in nulls.values()
    ])
    late = np.arange(plan['max_lag']) >= plan['late_lag_start'] - 1
    raw_symbols = np.asarray([letter != ' ' for letter in symbols])[:, None]
    results = {}
    for name, replicas in nulls.items():
        valid = np.isfinite(replicas).sum(axis=0)
        average = np.divide(np.nansum(replicas, axis=0), valid, out=np.full_like(observed, np.nan), where=valid > 0)
        results[name] = {
            'curve_mean': numeric(average),
            'glyph_all_lags': mean_summary(observed, replicas, common & raw_symbols),
            'glyph_late_lags': mean_summary(observed, replicas, common & raw_symbols & late),
            'space_late_lags': mean_summary(observed, replicas, common & ~raw_symbols & late),
        }
    return {'observed_curves': numeric(observed), 'common_coefficient_mask': common.tolist(), 'comparisons': results}


def manuscript(plan):
    alphabet = set(plan['ascii_eva'])
    views = {edition: corpus.split_pages('practice', edition) for edition in ('zl', 'it')}
    common = set.intersection(*(
        {line.id for p in eval_pages for line in p.lines if eligible(line, alphabet)}
        for _, eval_pages in views.values()
    ))
    training = {
        edition: [replace(page, lines=[line for line in page.lines if eligible(line, alphabet)]) for page in both[0]]
        for edition, both in views.items()
    }
    word_counts = {edition: generators.train_types(pages) for edition, pages in training.items()}
    glyph_counts = {
        edition: Counter({letter: sum(count * word.count(letter) for word, count in counts.items()) for letter in alphabet})
        for edition, counts in word_counts.items()
    }
    symbols = [letter for letter in plan['ascii_eva'] if all(c[letter] >= plan['min_train_count_both_editions'] for c in glyph_counts.values())] + [' ']
    answer = {'symbols': symbols, 'selection': {'shared_paragraph_loci': len(common)}, 'editions': {}}
    for edition, (_, selected) in views.items():
        pages, layout = source_layout(selected, common)
        book = to_book(pages, layout)
        results = {}
        for flatten in (False, True):
            local_plan = {**plan, 'flatten_pages': flatten}
            results['flattened' if flatten else 'within_page'] = {
                'observed': curves(book, symbols, local_plan),
                'nulls': {key: [] for key in ('global_word', 'page_line', 'paragraph_word', 'line_glyph_slots', 'self_citation', 'stationary_copy')},
            }
        for trial in range(plan['surrogates_per_model']):
            seed = plan['seed'] + trial
            fakes = {
                'global_word': shuffle_global_tokens(book, Random(seed)),
                'page_line': shuffle_whole_lines_within_page(book, Random(seed)),
                'paragraph_word': shuffle_whole_words_within_paragraph(book, Random(seed)),
                'line_glyph_slots': shuffle_line_glyph_slots(book, Random(seed)),
                'self_citation': to_book(generators.g_self_citation(training[edition], pages, seed=seed), layout),
                'stationary_copy': stationary_word_copy(book, word_counts[edition], Random(seed)),
            }
            for group, measured in results.items():
                local_plan = {**plan, 'flatten_pages': group == 'flattened'}
                for key, fake in fakes.items():
                    measured['nulls'][key].append(curves(fake, symbols, local_plan))
        answer['editions'][edition] = {
            'pages': len(pages),
            'words': sum(len(line.words) for page in pages for line in page.lines),
            **{
                group: compare(values['observed'], {k: np.stack(rows) for k, rows in values['nulls'].items()}, symbols, plan)
                for group, values in results.items()
            },
        }
        print(edition, len(pages), symbols, flush=True)
    return answer


def positive_long_rate_control(rng, plan, scenario):
    width = plan['sensitivity_block_width']
    number = plan['sensitivity_blocks']
    rates = plan['sensitivity_rates']
    pages = []
    for i in range(number):
        rate = rates[i % len(rates)] if scenario == 'rates_only' else plan['sensitivity_stationary_rate']
        if scenario in ('stationary_independent', 'rates_only'):
            page = rng.random(width) < rate
        else:
            positions = np.sort(rng.choice(width, int(width * rate), replace=False))
            gaps = np.diff(positions)
            innovation = rng.normal(size=len(gaps))
            serial = np.empty_like(innovation)
            serial[0] = innovation[0]
            rho = plan['sensitivity_ar_rho']
            for j in range(1, len(serial)):
                serial[j] = rho * serial[j - 1] + np.sqrt(1 - rho * rho) * innovation[j]
            reordered = np.empty_like(gaps)
            reordered[np.argsort(serial)] = np.sort(gaps)
            new_positions = positions[0] + np.r_[0, np.cumsum(reordered)]
            assert new_positions[0] == positions[0] and new_positions[-1] == positions[-1]
            assert np.array_equal(np.sort(np.diff(new_positions)), np.sort(gaps))
            page = np.zeros(width, dtype=bool)
            page[new_positions] = True
        pages.append(page)
    return pages


def synthetic_score(pages, plan):
    gaps = [np.diff(np.flatnonzero(page)) for page in pages]
    series = pearson_gap_curve(gaps, plan['max_lag'], plan['min_pairs_per_coefficient'])
    return float(series[plan['late_lag_start'] - 1:].mean())


def sensitivity(plan, scenarios=('stationary_independent', 'rates_only', 'dependent_gap_order')):
    rng = np.random.default_rng(plan['seed'] + 4000)
    output = {}
    for scenario in scenarios:
        tallies = Counter()
        means = []
        for _ in range(plan['sensitivity_books_per_case']):
            pages = positive_long_rate_control(rng, plan, scenario)
            observed = synthetic_score(pages, plan)
            means.append(observed)
            nulls = {key: [] for key in ('global_position', 'page_position', 'page_gap_order')}
            for _ in range(plan['sensitivity_surrogates']):
                shuffled = rng.permutation(np.concatenate(pages)).reshape(len(pages), -1)
                nulls['global_position'].append(synthetic_score(shuffled, plan))
                shuffled = [rng.permutation(page) for page in pages]
                nulls['page_position'].append(synthetic_score(shuffled, plan))
                reordered = []
                for page in pages:
                    positions = np.flatnonzero(page)
                    replacement = np.zeros_like(page)
                    replacement[positions[0] + np.r_[0, np.cumsum(rng.permutation(np.diff(positions)))]] = True
                    reordered.append(replacement)
                nulls['page_gap_order'].append(synthetic_score(reordered, plan))
            for key, values in nulls.items():
                p = (1 + sum(v >= observed - 1e-12 for v in values)) / (1 + len(values))
                tallies[key] += p <= .05
        output[scenario] = {'average_late_correlation': float(np.mean(means)), 'rejections_at_0_05': dict(tallies)}
    return output


def main():
    # Compare pooled lag-moment results to a direct Pearson calculation on a simple series.
    example = np.asarray([1, 2, 2, 4, 3, 7, 6], dtype=float)
    check = pearson_gap_curve([example], 3, 3)
    assert np.allclose(check, [np.corrcoef(example[:-lag], example[lag:])[0, 1] for lag in (1, 2, 3)])
    plan = json.loads(Path(sys.argv[1]).read_text())
    result = {'plan': plan, 'numpy': np.__version__, 'manuscript': manuscript(plan), 'sensitivity': sensitivity(plan)}
    Path(sys.argv[2]).write_text(json.dumps(result, indent=2, allow_nan=False) + '\n')
    for edition, result_part in result['manuscript']['editions'].items():
        for scope in ('within_page', 'flattened'):
            print(edition, scope, {key: compare['glyph_late_lags'] for key, compare in result_part[scope]['comparisons'].items()}, flush=True)
    print('sensitivity', result['sensitivity'], flush=True)


if __name__ == '__main__':
    main()

