"""Public-practice surrogates for the Voynich glyph-gap analysis."""

from collections import Counter, deque
from collections.abc import Iterator
from itertools import accumulate
from random import Random


type Book = list[list[list[list[str]]]]


def _tokens(book: Book) -> Iterator[str]:
    for page in book:
        for paragraph in page:
            for line in paragraph:
                yield from line


def _fill_layout(book: Book, tokens: Iterator[str]) -> Book:
    return [
        [[[next(tokens) for _ in line] for line in paragraph] for paragraph in page]
        for page in book
    ]


def shuffle_global_tokens(book: Book, rng: Random) -> Book:
    """Shuffle all words across the book, keeping each destination line length."""
    words = list(_tokens(book))
    rng.shuffle(words)
    return _fill_layout(book, iter(words))


def shuffle_whole_lines_within_page(book: Book, rng: Random) -> Book:
    """Permute complete lines per page, keeping each paragraph's number of lines."""
    shuffled = []
    for page in book:
        lines = [list(line) for paragraph in page for line in paragraph]
        rng.shuffle(lines)
        line_source = iter(lines)
        shuffled.append([[next(line_source) for _ in paragraph] for paragraph in page])
    return shuffled


def shuffle_whole_words_within_paragraph(book: Book, rng: Random) -> Book:
    """Permute words within each paragraph, keeping each destination line length."""
    shuffled = []
    for page in book:
        shuffled_page = []
        for paragraph in page:
            words = [word for line in paragraph for word in line]
            rng.shuffle(words)
            word_source = iter(words)
            shuffled_page.append([[next(word_source) for _ in line] for line in paragraph])
        shuffled.append(shuffled_page)
    return shuffled


def stationary_word_copy(book: Book, base: Counter[str], rng: Random) -> Book:
    """Fill the layout from weighted public words and a 33% recent-token copy rule.

    A copy picks uniformly among the previous 30 generated token positions.
    The memory persists across line, paragraph and page boundaries. The first
    word is drawn from the base because the memory begins empty.
    """
    counts = [(word, count) for word, count in sorted(base.items()) if count > 0]
    if not counts:
        if any(True for _ in _tokens(book)):
            raise ValueError("base must contain a word with positive weight")
        return _fill_layout(book, iter(()))
    vocabulary, weights = zip(*counts)
    cumulative_weights = tuple(accumulate(weights))
    recent: deque[str] = deque(maxlen=30)

    def generate() -> Iterator[str]:
        while True:
            if recent and rng.random() < 0.33:
                word = rng.choice(recent)
            else:
                word = rng.choices(vocabulary, cum_weights=cumulative_weights)[0]
            recent.append(word)
            yield word

    return _fill_layout(book, generate())
